package in.carenest.clinic.api;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.lowagie.text.Document;
import com.lowagie.text.FontFactory;
import com.lowagie.text.Paragraph;
import com.lowagie.text.pdf.PdfWriter;
import in.carenest.clinic.security.SecurityConfig.TenantPrincipal;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.io.ByteArrayOutputStream;
import java.time.*;
import java.util.*;

@RestController @RequestMapping("/api")
public class PatientRecordsApi {
 private final JdbcTemplate db; private final ObjectMapper json;
 public PatientRecordsApi(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}

 public record Medicine(@NotBlank String medicineName,String dosage,String frequency,String duration,String instructions,Integer sortOrder){}
 public record PrescriptionRequest(@NotNull UUID customerId,UUID queueEntryId,String diagnosis,String clinicalNotes,String advice,LocalDate followUpOn,List<@Valid Medicine> items,Boolean sign){}

 @PostMapping("/prescriptions") @Transactional @ResponseStatus(HttpStatus.CREATED)
 public Map<String,Object> createPrescription(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody PrescriptionRequest x){
  tenant(p);doctor(p);requireCustomer(p.clinicId(),x.customerId());
  if(x.queueEntryId()!=null&&db.queryForObject("select count(*) from queue_entries where id=? and clinic_id=?",Integer.class,x.queueEntryId(),p.clinicId())==0)throw new RecordError(HttpStatus.BAD_REQUEST,"Queue entry does not belong to this clinic");
  UUID id=UUID.randomUUID();boolean signed=Boolean.TRUE.equals(x.sign());
  db.update("insert into prescriptions(id,clinic_id,branch_id,customer_id,queue_entry_id,doctor_user_id,diagnosis,clinical_notes,advice,follow_up_on,status,signed_at) values(?,?,?,?,?,?,?,?,?,?,?,case when ? then now() else null end)",id,p.clinicId(),p.branchId(),x.customerId(),x.queueEntryId(),p.userId(),x.diagnosis(),x.clinicalNotes(),x.advice(),x.followUpOn(),signed?"SIGNED":"DRAFT",signed);
  if(x.items()!=null)for(Medicine m:x.items())db.update("insert into prescription_items(clinic_id,prescription_id,medicine_name,dosage,frequency,duration,instructions,sort_order) values(?,?,?,?,?,?,?,?)",p.clinicId(),id,m.medicineName(),m.dosage(),m.frequency(),m.duration(),m.instructions(),m.sortOrder()==null?0:m.sortOrder());
  db.update("insert into patient_history_events(clinic_id,branch_id,customer_id,queue_entry_id,event_type,event_data,actor_user_id) values(?,?,?,?, 'PRESCRIPTION_CREATED',jsonb_build_object('prescriptionId',?::text,'status',?),?)",p.clinicId(),p.branchId(),x.customerId(),x.queueEntryId(),id.toString(),signed?"SIGNED":"DRAFT",p.userId());
  return Map.of("id",id,"status",signed?"SIGNED":"DRAFT");
 }

 @GetMapping("/patients/{customerId}/history")
 public Map<String,Object> patientHistory(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID customerId){
  tenant(p);var patient=requireCustomer(p.clinicId(),customerId);Map<String,Object> out=new LinkedHashMap<>();out.put("patient",patient);
  out.put("queueVisits",db.queryForList("select id,queue_date,queue_period,token_number,age,weight_kg,bp,sugar,status,started_at,completed_at,created_at from queue_entries where clinic_id=? and customer_id=? order by created_at desc",p.clinicId(),customerId));
  out.put("prescriptions",db.queryForList("select p.id,p.diagnosis,p.clinical_notes,p.advice,p.follow_up_on,p.status,p.signed_at,p.created_at,u.display_name doctor,(select coalesce(jsonb_agg(jsonb_build_object('medicineName',i.medicine_name,'dosage',i.dosage,'frequency',i.frequency,'duration',i.duration,'instructions',i.instructions) order by i.sort_order),'[]'::jsonb) from prescription_items i where i.prescription_id=p.id and i.clinic_id=p.clinic_id) items from prescriptions p join users u on u.id=p.doctor_user_id where p.clinic_id=? and p.customer_id=? order by p.created_at desc",p.clinicId(),customerId));
  out.put("receipts",db.queryForList("select id,amount,adjustment,status,method,receipt_number,receipt_url,created_at,confirmed_at from payments where clinic_id=? and customer_id=? order by created_at desc",p.clinicId(),customerId));
  out.put("certificates",db.queryForList("select id,certificate_number,certificate_type,title,valid_from,valid_until,status,issued_at,created_at from patient_certificates where clinic_id=? and customer_id=? order by created_at desc",p.clinicId(),customerId));
  out.put("events",db.queryForList("select event_type,event_data,created_at from patient_history_events where clinic_id=? and customer_id=? order by created_at desc limit 250",p.clinicId(),customerId));return out;
 }

 public record CertificateRequest(@NotNull UUID customerId,UUID queueEntryId,@NotBlank String certificateType,String templateKey,@NotBlank String title,@NotBlank String body,LocalDate validFrom,LocalDate validUntil,Map<String,Object> certificateData,Boolean issue){}
 @PostMapping("/certificates") @Transactional @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> createCertificate(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody CertificateRequest x){tenant(p);if(!List.of("PRACTITIONER","RECEPTIONIST","OWNER").contains(p.role()))throw new RecordError(HttpStatus.FORBIDDEN,"Clinic staff access required");requireCustomer(p.clinicId(),x.customerId());boolean issued=Boolean.TRUE.equals(x.issue());String number=issued?"CERT-"+LocalDate.now().getYear()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase():null;UUID id=UUID.randomUUID();db.update("insert into patient_certificates(id,clinic_id,branch_id,customer_id,queue_entry_id,certificate_number,certificate_type,template_key,title,body,valid_from,valid_until,certificate_data,status,created_by,approved_by,issued_at) values(?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?,?,case when ? then now() else null end)",id,p.clinicId(),p.branchId(),x.customerId(),x.queueEntryId(),number,x.certificateType(),x.templateKey(),x.title(),x.body(),x.validFrom(),x.validUntil(),toJson(x.certificateData()),issued?"ISSUED":"DRAFT",p.userId(),issued?p.userId():null,issued);db.update("insert into patient_history_events(clinic_id,branch_id,customer_id,queue_entry_id,event_type,event_data,actor_user_id) values(?,?,?,?, 'CERTIFICATE_CREATED',jsonb_build_object('certificateId',?::text,'type',?,'status',?),?)",p.clinicId(),p.branchId(),x.customerId(),x.queueEntryId(),id.toString(),x.certificateType(),issued?"ISSUED":"DRAFT",p.userId());Map<String,Object> out=new LinkedHashMap<>();out.put("id",id);out.put("certificateNumber",number);out.put("status",issued?"ISSUED":"DRAFT");out.put("pdfUrl","/api/certificates/"+id+"/pdf");return out;}

 @GetMapping(value="/certificates/{id}/pdf",produces=MediaType.APPLICATION_PDF_VALUE) public ResponseEntity<byte[]> certificatePdf(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id){tenant(p);var x=db.queryForMap("select pc.certificate_number,pc.certificate_type,pc.title,pc.body,pc.valid_from,pc.valid_until,pc.status,pc.issued_at,c.full_name patient,cl.name clinic,b.name branch,u.display_name issued_by from patient_certificates pc join customers c on c.id=pc.customer_id join clinics cl on cl.id=pc.clinic_id join branches b on b.id=pc.branch_id join users u on u.id=pc.created_by where pc.id=? and pc.clinic_id=?",id,p.clinicId());ByteArrayOutputStream bytes=new ByteArrayOutputStream();Document doc=new Document();PdfWriter.getInstance(doc,bytes);doc.open();doc.add(new Paragraph(String.valueOf(x.get("clinic")),FontFactory.getFont(FontFactory.HELVETICA_BOLD,20)));doc.add(new Paragraph(String.valueOf(x.get("branch"))));doc.add(new Paragraph(" "));doc.add(new Paragraph(String.valueOf(x.get("title")),FontFactory.getFont(FontFactory.HELVETICA_BOLD,16)));if(x.get("certificate_number")!=null)doc.add(new Paragraph("Certificate: "+x.get("certificate_number")));doc.add(new Paragraph("Patient: "+x.get("patient")));doc.add(new Paragraph("Type: "+x.get("certificate_type")));doc.add(new Paragraph(" "));doc.add(new Paragraph(String.valueOf(x.get("body"))));doc.add(new Paragraph(" "));if(x.get("valid_from")!=null)doc.add(new Paragraph("Valid from: "+x.get("valid_from")));if(x.get("valid_until")!=null)doc.add(new Paragraph("Valid until: "+x.get("valid_until")));doc.add(new Paragraph("Issued by: "+x.get("issued_by")));doc.add(new Paragraph("Status: "+x.get("status")));doc.close();String filename=x.get("certificate_number")==null?"certificate-draft":String.valueOf(x.get("certificate_number"));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+filename+".pdf\"").body(bytes.toByteArray());}

 @GetMapping("/messages") public List<Map<String,Object>> messageHistory(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(required=false) String channel){tenant(p);return db.queryForList("select o.id,o.channel,o.sender,o.recipient,o.message_type,o.body,o.status,o.created_at,(select e.delivery_status from message_delivery_events e where e.outbox_id=o.id and e.clinic_id=o.clinic_id order by e.occurred_at desc limit 1) delivery_status,(select e.occurred_at from message_delivery_events e where e.outbox_id=o.id and e.clinic_id=o.clinic_id order by e.occurred_at desc limit 1) delivered_at from message_outbox o where o.clinic_id=? and (? is null or o.channel=?) order by o.created_at desc limit 500",p.clinicId(),channel,channel);}

 public record CounterReset(@Min(0) int currentToken){}
 @PostMapping("/queue/reset") @Transactional public Map<String,Object> resetOwnCounter(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody CounterReset x){tenant(p);doctor(p);resetCounter(p.clinicId(),p.branchId(),p.userId(),x.currentToken());return Map.of("status","RESET","currentToken",x.currentToken());}
 @PostMapping("/admin/clinics/{clinicId}/branches/{branchId}/counter/reset") @Transactional public Map<String,Object> resetAdminCounter(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID clinicId,@PathVariable UUID branchId,@RequestBody(required=false) CounterReset x){admin(p);int value=x==null?0:x.currentToken();resetCounter(clinicId,branchId,p.userId(),value);return Map.of("status","RESET","currentToken",value);}

 @GetMapping("/configuration") public Map<String,Object> configuration(@AuthenticationPrincipal TenantPrincipal p){tenant(p);return configurationFor(p.clinicId(),p.branchId());}
 @GetMapping("/admin/clinics/{clinicId}/configuration") public Map<String,Object> adminConfiguration(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID clinicId,@RequestParam UUID branchId){admin(p);return configurationFor(clinicId,branchId);}

 public record SessionConfig(UUID id,@NotBlank String code,@NotBlank String displayName,@NotNull LocalTime startsAt,@NotNull LocalTime endsAt,Boolean active,Integer sortOrder){}
 public record ChannelConfig(@NotBlank String channel,Boolean enabled,@NotBlank String senderSource,String clinicNumber,String providerName,String providerAccountRef,Map<String,Object> templates){}
 public record ConfigurationUpdate(@NotNull UUID branchId,List<@Valid SessionConfig> sessions,List<@Valid ChannelConfig> channels,Map<String,Object> settings){}

 @PutMapping("/configuration") @Transactional public Map<String,Object> saveConfiguration(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody ConfigurationUpdate x){tenant(p);owner(p);saveConfiguration(p.clinicId(),p.userId(),x);return Map.of("status","SAVED");}
 @PutMapping("/admin/clinics/{clinicId}/configuration") @Transactional public Map<String,Object> saveAdminConfiguration(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID clinicId,@Valid @RequestBody ConfigurationUpdate x){admin(p);saveConfiguration(clinicId,p.userId(),x);return Map.of("status","SAVED");}

 public record PlatformConfiguration(String defaultSmsNumber,String defaultWhatsappNumber,Map<String,Object> settings){}
 @GetMapping("/admin/platform-configuration") public Map<String,Object> platformConfiguration(@AuthenticationPrincipal TenantPrincipal p){admin(p);return db.queryForMap("select default_sms_number,default_whatsapp_number,settings,updated_at from platform_configuration where id=1");}
 @PutMapping("/admin/platform-configuration") public Map<String,Object> savePlatformConfiguration(@AuthenticationPrincipal TenantPrincipal p,@RequestBody PlatformConfiguration x){admin(p);db.update("update platform_configuration set default_sms_number=?,default_whatsapp_number=?,settings=?::jsonb,updated_at=now() where id=1",x.defaultSmsNumber(),x.defaultWhatsappNumber(),toJson(x.settings()));return Map.of("status","SAVED");}

 public record MenuPermission(String role,String menuKey,Boolean enabled){}
 @GetMapping("/admin/clinics/{clinicId}/menu-configuration") public List<Map<String,Object>> menuConfiguration(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID clinicId){admin(p);return db.queryForList("select role,menu_key,enabled from clinic_role_menu_configuration where clinic_id=? order by role,menu_key",clinicId);}
 @PutMapping("/admin/clinics/{clinicId}/menu-configuration") @Transactional public Map<String,Object> saveMenuConfiguration(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID clinicId,@RequestBody List<MenuPermission> items){admin(p);for(MenuPermission item:items){if(!List.of("RECEPTIONIST","PRACTITIONER").contains(item.role()))throw new RecordError(HttpStatus.BAD_REQUEST,"Unsupported clinic role");db.update("insert into clinic_role_menu_configuration(clinic_id,role,menu_key,enabled) values(?,?,?,?) on conflict(clinic_id,role,menu_key) do update set enabled=excluded.enabled,updated_at=now()",clinicId,item.role(),item.menuKey(),Boolean.TRUE.equals(item.enabled()));}return Map.of("status","SAVED");}

 private void saveConfiguration(UUID clinic,UUID actor,ConfigurationUpdate x){Integer branch=db.queryForObject("select count(*) from branches where id=? and clinic_id=?",Integer.class,x.branchId(),clinic);if(branch==null||branch==0)throw new RecordError(HttpStatus.BAD_REQUEST,"Branch does not belong to this clinic");if(x.sessions()!=null)for(SessionConfig s:x.sessions())db.update("insert into clinic_sessions(id,clinic_id,branch_id,code,display_name,starts_at,ends_at,active,sort_order) values(coalesce(?,gen_random_uuid()),?,?,?,?,?,?,?,?) on conflict(branch_id,code) do update set display_name=excluded.display_name,starts_at=excluded.starts_at,ends_at=excluded.ends_at,active=excluded.active,sort_order=excluded.sort_order,updated_at=now()",s.id(),clinic,x.branchId(),s.code(),s.displayName(),s.startsAt(),s.endsAt(),s.active()==null||s.active(),s.sortOrder()==null?0:s.sortOrder());if(x.channels()!=null)for(ChannelConfig c:x.channels())db.update("insert into clinic_communication_settings(clinic_id,channel,enabled,sender_source,clinic_number,provider_name,provider_account_ref,templates) values(?,?,?,?,?,?,?,?::jsonb) on conflict(clinic_id,channel) do update set enabled=excluded.enabled,sender_source=excluded.sender_source,clinic_number=excluded.clinic_number,provider_name=excluded.provider_name,provider_account_ref=excluded.provider_account_ref,templates=excluded.templates,updated_at=now()",clinic,c.channel(),Boolean.TRUE.equals(c.enabled()),c.senderSource(),c.clinicNumber(),c.providerName(),c.providerAccountRef(),toJson(c.templates()));db.update("insert into clinic_settings(clinic_id,settings,updated_by) values(?,?::jsonb,?) on conflict(clinic_id) do update set settings=excluded.settings,updated_by=excluded.updated_by,updated_at=now()",clinic,toJson(x.settings()),actor);}
 private Map<String,Object> configurationFor(UUID clinic,UUID branch){Integer valid=db.queryForObject("select count(*) from branches where id=? and clinic_id=?",Integer.class,branch,clinic);if(valid==null||valid==0)throw new RecordError(HttpStatus.NOT_FOUND,"Clinic branch not found");Map<String,Object> out=new LinkedHashMap<>();out.put("sessions",db.queryForList("select id,code,display_name,starts_at,ends_at,active,sort_order from clinic_sessions where clinic_id=? and branch_id=? order by sort_order",clinic,branch));out.put("channels",db.queryForList("select channel,enabled,sender_source,clinic_number,provider_name,provider_account_ref,templates from clinic_communication_settings where clinic_id=? order by channel",clinic));out.put("qrCode",db.queryForMap("select id,public_code,purpose,active,created_at,rotated_at from clinic_qr_codes where clinic_id=?",clinic));out.put("settings",db.queryForObject("select settings from clinic_settings where clinic_id=?",Object.class,clinic));return out;}
 private void resetCounter(UUID clinic,UUID branch,UUID actor,int value){Integer valid=db.queryForObject("select count(*) from branches where id=? and clinic_id=?",Integer.class,branch,clinic);if(valid==null||valid==0)throw new RecordError(HttpStatus.NOT_FOUND,"Clinic branch not found");db.update("insert into daily_queue_counters(clinic_id,branch_id,counter_date,last_issued_token,current_token,reset_at) values(?,?,current_date,?,?,now()) on conflict(branch_id,counter_date) do update set current_token=excluded.current_token,last_issued_token=greatest(daily_queue_counters.last_issued_token,excluded.current_token),reset_at=now(),updated_at=now()",clinic,branch,value,value);db.update("update branches set current_token=? where id=? and clinic_id=?",value,branch,clinic);db.update("insert into patient_history_events(clinic_id,branch_id,event_type,event_data,actor_user_id) values(?,?, 'COUNTER_RESET',jsonb_build_object('currentToken',?),?)",clinic,branch,value,actor);}
 private Map<String,Object> requireCustomer(UUID clinic,UUID customer){var rows=db.queryForList("select id,full_name,phone,email,dob,age,address,guardian_name,guardian_phone,joined_on,active from customers where id=? and clinic_id=?",customer,clinic);if(rows.isEmpty())throw new RecordError(HttpStatus.NOT_FOUND,"Patient not found");return rows.getFirst();}
 private String toJson(Object value){try{return json.writeValueAsString(value==null?Map.of():value);}catch(Exception e){throw new RecordError(HttpStatus.BAD_REQUEST,"Configuration contains invalid data");}}
 private void tenant(TenantPrincipal p){if(p==null||p.clinicId()==null)throw new RecordError(HttpStatus.FORBIDDEN,"A clinic context is required");} private void doctor(TenantPrincipal p){if(!List.of("PRACTITIONER","OWNER").contains(p.role()))throw new RecordError(HttpStatus.FORBIDDEN,"Doctor access required");} private void owner(TenantPrincipal p){if(!"OWNER".equals(p.role()))throw new RecordError(HttpStatus.FORBIDDEN,"Clinic owner access required");} private void admin(TenantPrincipal p){if(p==null||!"PLATFORM_ADMIN".equals(p.role()))throw new RecordError(HttpStatus.FORBIDDEN,"Platform administrator required");}
 @ResponseStatus class RecordError extends RuntimeException{final HttpStatus status;RecordError(HttpStatus s,String m){super(m);status=s;}} @ExceptionHandler(RecordError.class) ResponseEntity<?> error(RecordError e){return ResponseEntity.status(e.status).body(Map.of("error",e.getMessage()));}
}
